namespace {EngineFacade* active=nullptr;uint64_t integer(const QJsonValue& v){return v.toString().toULongLong();}template<size_t N>void text(char(&dst)[N],QString value){auto b=value.toUtf8();auto n=std::min(size_t(b.size()),N-1);std::memcpy(dst,b.data(),n);dst[n]=0;}}
EngineFacade* EngineFacade::current(){return active;}
EngineFacade::~EngineFacade(){active=nullptr;client_.connectionChanged={};client_.fault={};}
EngineFacade::EngineFacade(const QString& endpoint,QObject* parent):QObject(parent){active=this;
 client_.connectionChanged=[this](bool connected){polling_=false;session_=0;telemetry_->graphReady=connected;if(connected){request({{"action","describe"}},[this](const QJsonObject& r){if(r["ok"].toBool())metadata_=r["data"].toObject();});request({{"action","devices"}},[this](const QJsonObject& r){if(r["ok"].toBool())devices_=r["data"].toObject();});poll();}else{lastQpc_=0;telemetry_->outputGateClosed=1;bridge_.publish(*telemetry_);}};
 client_.fault=[this](QString error){text(telemetry_->outputDetail,error);bridge_.publish(*telemetry_);};
 poll_.setInterval(100);connect(&poll_,&QTimer::timeout,this,[this]{poll();});poll_.start();client_.connectToCore(endpoint);
}
bool EngineFacade::request(QJsonObject q,IpcClient::Reply callback){if(session_)q["session"]=QString::number(session_);return client_.send(q,[this,callback=std::move(callback)](const QJsonObject& reply){if(reply.contains("session"))session_=integer(reply["session"]);if(callback)callback(reply);});}
void EngineFacade::poll(){if(polling_||!connected())return;polling_=request({{"action","telemetry"}},[this](const QJsonObject& r){polling_=false;if(r["ok"].toBool())receive(r["data"].toObject());});}
void EngineFacade::receive(const QJsonObject& v){
 for(const auto key:{"crossoverPeaks","outputs","protectionState"})if(v[key].toArray().size()!=16){client_.fault("Malformed telemetry dimensions");return;}
 auto checkView=v["view"].toObject();if(checkView["response"].toArray().size()!=16||checkView["frequency"].toArray().size()!=256||checkView["spectrum"].toArray().size()!=256||v["matrix"].toObject()["routes"].toArray().size()!=16||v["headroom"].toObject()["groups"].toArray().size()>16)return;
 for(const auto row:checkView["response"].toArray())if(row.toArray().size()!=256)return;
 auto& s=*telemetry_;s.structSize=sizeof(s);s.enginePid=uint32_t(v["pid"].toInt());s.graphReady=1;s.inputCount=3;text(s.inputs[0].detail,v["inputState"].toString());s.heartbeat=integer(v["blocks"]);s.sequence++;s.outputArmed=v["armed"].toBool();s.outputGateClosed=!s.outputArmed;s.outputDomainCount=2;sequence_=std::max(sequence_,integer(v["accepted"]));text(s.outputDetail,lastError_.isEmpty()?v["hardwareGate"].toString():lastError_);
 s.crossoverControlAvailable=s.crossoverTelemetryAvailable=1;s.crossoverSampleRate=192000;s.crossoverBlockSize=uint32_t(v["blockSize"].toInt());s.crossoverCinemaProgram=uint32_t(v["program"].toInt());s.crossoverControlAppliedSequence=integer(v["crossoverApplied"]);s.crossoverCommandAcceptedSequence=integer(v["crossoverAccepted"]);s.crossoverCommandAppliedSequence=s.crossoverControlAppliedSequence;s.crossoverCommandFailedSequence=integer(v["crossoverFailed"]);s.crossoverCommandReason=v["crossoverReason"].toInt();s.crossoverCommandState=s.crossoverCommandAcceptedSequence==s.crossoverCommandAppliedSequence?ENTROPY_CROSSOVER_COMMAND_APPLIED:ENTROPY_CROSSOVER_COMMAND_ACCEPTED;
 auto parameters=v["parameters"].toArray();s.crossoverParameterCount=uint32_t(std::min(qsizetype(host::crossoverParameterCapacity),parameters.size()));for(unsigned i=0;i<s.crossoverParameterCount;++i){auto p=parameters[int(i)].toObject();text(s.crossoverParameters[i].identifier,p["id"].toString());s.crossoverParameters[i].value=p["value"].toDouble();}
 auto peaks=v["crossoverPeaks"].toArray(),outputs=v["outputs"].toArray();for(int i=0;i<16;++i){s.crossoverOutputPeaks[i]=peaks[i].toDouble();auto out=outputs[i].toObject();text(s.outputMatrixRoleLabel[i],out["label"].toString());text(s.outputMatrixRoleId[i],QString("CROSSOVER_OUT_%1").arg(i+1));text(s.outputMatrixLaneLabel[i],QString("Lane %1").arg(i+1));text(s.headroomLaneLabel[i],out["label"].toString());}
 auto music=v["musicPeaks"].toArray(),cinema=v["cinemaPeaks"].toArray(),protection=v["protectionState"].toArray();for(int i=0;i<3;++i)s.crossoverMusicInputPeaks[i]=music[i].toDouble();for(int i=0;i<10;++i)s.crossoverCinemaInputPeaks[i]=cinema[i].toDouble();for(int i=0;i<16;++i)s.crossoverProtectionState[i]=uint32_t(protection[i].toInt());s.crossoverProtectionAvailable=1;s.crossoverProtectionEnabledMask=v["protectionEnabled"].toInt();s.crossoverProtectionWarningMask=v["protectionWarning"].toInt();s.crossoverProtectionTrippedMask=v["protectionTripped"].toInt();s.crossoverProtectionGlobalTrip=s.crossoverProtectionTrippedMask!=0;s.crossoverLatencySamples=v["firLatency"].toInt();s.crossoverCommandKind=v["crossoverKind"].toInt();
 auto view=v["view"].toObject();auto response=view["response"].toArray();s.crossoverViewTelemetryAvailable=1;s.crossoverResponsePoints=256;s.crossoverSpectrumPoints=view["spectrumAvailable"].toBool()?256:0;s.crossoverMonitoredChannel=view["monitor"].toInt();auto vf=view["frequency"].toArray(),vs=view["spectrum"].toArray();for(int i=0;i<16;++i){auto row=response[i].toArray();for(int n=0;n<256;++n)s.crossoverResponseDb[i][n]=float(row[n].toDouble());}for(int n=0;n<256;++n){s.crossoverSpectrumFrequencyHz[n]=float(vf[n].toDouble());s.crossoverSpectrumDb[n]=float(vs[n].toDouble());}
 auto m=v["matrix"].toObject();s.outputMatrixAvailable=1;s.outputMatrixGeneration=m["generation"].toInt();s.outputMatrixAppliedSequence=integer(m["appliedSequence"]);s.outputMatrixActiveSourceMask=uint32_t(m["activeSourceMask"].toInt());s.outputMatrixEnabledDestinationMask=uint32_t(m["enabledDestinationMask"].toInt());s.outputMatrixSummingDestinationMask=uint32_t(m["summingMask"].toInt());s.outputMatrixOrphanedSourceMask=uint32_t(m["orphanMask"].toInt());s.outputMatrixRouteCount=uint32_t(m["routeCount"].toInt());auto routes=m["routes"].toArray(),mp=m["peaks"].toArray();for(int i=0;i<16;++i){s.outputMatrixSourceDestinationMask[i]=uint32_t(routes[i].toInt());s.outputMatrixDestinationPeaks[i]=mp[i].toDouble();s.outputMatrixLaneStatus[i]=host::EngineOutputLaneUnassigned;}
 auto h=v["headroom"].toObject();s.headroomAvailable=s.headroomModeAvailable=s.headroomTimingAvailable=1;s.headroomStateRevision=s.headroomAppliedRevision=h["revision"].toInt();s.headroomAppliedSequence=integer(h["appliedSequence"]);s.headroomModeTransitionActive=h["modeTransitionActive"].toInt();s.headroomModeTransitionProgress=h["modeTransitionProgress"].toDouble();s.headroomAnalyzerState=h["analyzerState"].toInt();s.headroomTruePeakStatus=h["truePeakStatus"].toInt();s.headroomMeasuredInputPeak=h["measuredPeak"].toDouble();s.headroomMeasuredInputTruePeak=h["truePeak"].toDouble();s.headroomAutoAnalysisReductionDb=h["analysisReductionDb"].toDouble();auto hp=h["peaks"].toArray();for(int i=0;i<16;++i)s.headroomChannelInputPeak[i]=hp[i].toDouble();s.headroomFaultFlags=h["faults"].toInt();s.headroomRequestedMode=h["mode"].toInt();s.headroomEffectiveMode=h["effectiveMode"].toInt();s.headroomFixedAttenuationDb=h["manualGainDb"].toDouble();s.headroomTransitionMs=h["transition"].toDouble();s.headroomAutoAttackMs=h["attack"].toDouble();s.headroomAutoReleaseMs=h["release"].toDouble();auto groups=h["groups"].toArray(),channelGroups=h["channelGroups"].toArray();s.headroomGroupCount=uint32_t(groups.size());s.headroomActiveChannelMask=0xffff;for(int i=0;i<16;++i)s.headroomChannelGroup[i]=uint32_t(channelGroups[i].toInt());for(int i=0;i<groups.size();++i){auto g=groups[i].toObject();s.headroomGroupBounded[i]=1;s.headroomCurrentGain[i]=g["gain"].toDouble();s.headroomTargetGain[i]=g["target"].toDouble();s.headroomGainReductionDb[i]=g["reductionDb"].toDouble();s.headroomRequiredDb[i]=g["required"].toDouble();s.headroomReserveMarginDb[i]=g["margin"].toDouble();s.headroomTransitionProgress[i]=g["progress"].toDouble();s.headroomGroupStatus[i]=g["status"].toInt();s.headroomPreventiveReserveDb[i]=g["reserve"].toDouble();}
 auto scheduling=v["scheduler"].toObject();s.engineCycleUs=scheduling["callbackWallUs"].toDouble();s.engineCycleMaxUs=scheduling["maximumCallbackWallUs"].toDouble();s.engineMaxLatenessUs=scheduling["maximumSchedulerLatenessUs"].toDouble();s.engineDeadlineMisses=integer(scheduling["callbackWallDeadlineMisses"]);s.outputFaultLatched=scheduling["faults"].toInt();LARGE_INTEGER now;QueryPerformanceCounter(&now);lastQpc_=uint64_t(now.QuadPart);bridge_.publish(s);
}
bool EngineFacade::submit(const host::EngineControlSnapshot& c,uint64_t& sequence){
 using namespace host;QJsonObject q;QString action;
 if(c.parameterSequence){action=c.parameterAction==EngineParameterSet?"parameter":"gesture";q["id"]=QString::fromUtf8(c.parameterIdentifier);q["value"]=c.parameterValue;q["begin"]=c.parameterAction==EngineParameterBeginGesture;}
 else if(c.crossoverMonitorSequence){action="monitor";q["channel"]=c.crossoverMonitorChannel;}
 else if(c.crossoverBulkSequence){switch(c.crossoverBulkAction){case EngineCrossoverApplySideDelay:action="apply-side-delay";break;case EngineCrossoverApplyLeftToRight:action="left-to-right";break;case EngineCrossoverResetProtectionTrip:action="reset-protection";q["channel"]=c.crossoverBulkValue;break;default:action="reset-all-protection";}q["cinema"]=bool(c.crossoverBulkProgram);q["right"]=bool(c.crossoverBulkSide);q["value"]=c.crossoverBulkValue;}
 else if(c.outputMatrixSequence){action=c.outputMatrixAction==EngineOutputMatrixClearAll?"matrix-clear":"matrix-route";q["source"]=int(c.outputMatrixSource);q["destination"]=int(c.outputMatrixDestination);q["enabled"]=bool(c.outputMatrixEnabled);}
 else if(c.headroomSequence){switch(c.headroomAction){case EngineHeadroomSetTransitionMs:action="headroom-transition";break;case EngineHeadroomSetGroupCount:action="headroom-groups";q["value"]=int(c.headroomIndex);break;case EngineHeadroomSetChannelGroup:action="headroom-channel-group";q["channel"]=int(c.headroomIndex);q["group"]=int(c.headroomSecondaryIndex);break;case EngineHeadroomSetPreventiveReserve:action="headroom-reserve";q["group"]=int(c.headroomIndex);break;case EngineHeadroomClearFault:action="headroom-clear-fault";break;case EngineHeadroomSetOperatingMode:action="headroom-policy";q["mode"]=int(c.headroomIndex);q["manualGainDb"]=c.headroomValue;break;case EngineHeadroomSetAutoAttackMs:action="headroom-attack";break;case EngineHeadroomSetAutoReleaseMs:action="headroom-release";break;default:return false;}if(!q.contains("value"))q["value"]=c.headroomValue;}
 else if(c.hardwareOutputSequence){action=c.hardwareOutputAction==EngineHardwareOutputArm?"arm":c.hardwareOutputAction==EngineHardwareOutputDisarm?"disarm":"configure-devices";QJsonArray domains;for(const auto& d:c.hardwareOutputDomains){QJsonArray lanes;for(unsigned i=0;i<d.channels;++i)lanes.append(int(d.destinationLaneForChannel[i]));domains.append(QJsonObject{{"enabled",bool(d.enabled)},{"endpoint",QString::fromUtf8(d.verifiedEndpointIdUtf8)},{"logicalId",QString::fromUtf8(d.logicalDeviceId)},{"approvalRevision",QString::number(d.approvalRevision)},{"rate",int(d.sampleRate)},{"channels",int(d.channels)},{"format",int(d.outputFormat)},{"lanes",lanes}});}q["domains"]=domains;}
 else if(c.projectSequence){action=c.projectAction==EngineProjectSave?"save-profile":"load-profile";q["path"]=QString::fromWCharArray(c.projectPath);}else return false;
 q["action"]=action;sequence=++sequence_;q["sequence"]=QString::number(sequence);auto requested=sequence;if(c.parameterSequence||c.crossoverBulkSequence||c.crossoverMonitorSequence)telemetry_->crossoverCommandRequestedSequence=requested;
 return request(q,[this,requested,c](const QJsonObject& r){auto& s=*telemetry_;if(!r["ok"].toBool()){lastError_=r["error"].toString();text(s.outputDetail,lastError_);if(c.parameterSequence||c.crossoverBulkSequence||c.crossoverMonitorSequence){s.crossoverCommandFailedSequence=requested;s.crossoverCommandState=ENTROPY_CROSSOVER_COMMAND_FAILED;}if(c.projectSequence){s.projectStatus=host::EngineProjectFailed;text(s.projectDetail,r["error"].toString());s.projectAppliedSequence=requested;}}
 else{lastError_.clear();auto data=r["data"].toObject();sequence_=std::max(sequence_,integer(data["accepted"]));if(c.parameterSequence&&c.parameterAction==host::EngineParameterSet){text(s.crossoverLastParameter,QString::fromUtf8(c.parameterIdentifier));s.crossoverLastValue=c.parameterValue;}if(c.projectSequence){s.projectStatus=c.projectAction==host::EngineProjectSave?host::EngineProjectSaved:host::EngineProjectLoaded;s.projectAppliedSequence=requested;if(c.projectAction==host::EngineProjectLoad&&data.contains("devices"))devices_=data["devices"].toObject();}if(c.hardwareOutputSequence){s.outputAppliedSequence=requested;if(data.contains("configuration"))devices_=data;}}bridge_.publish(s);poll();});
}
